//! Routing between [`Service`]s and handlers.

use self::{future::RouterFuture, not_found::NotFound};
use crate::{
    body::{boxed, Body, Bytes, HttpBody},
    extract::{
        connect_info::{Connected, IntoMakeServiceWithConnectInfo},
        MatchedPath, OriginalUri,
    },
    response::Response,
    routing::strip_prefix::StripPrefix,
    util::{try_downcast, ByteStr, PercentDecodedByteStr},
    BoxError,
};
use http::{header, HeaderValue, Method, Request, StatusCode, Uri};
use serde::de::DeserializeOwned;
use std::{
    borrow::Cow,
    collections::HashMap,
    convert::{Infallible, TryFrom},
    fmt,
    sync::Arc,
    task::{Context, Poll},
};
use tower::{layer::layer_fn, ServiceBuilder, ServiceExt};
use tower_http::map_response_body::MapResponseBodyLayer;
use tower_layer::Layer;
use tower_service::Service;

pub mod future;

mod into_make_service;
mod method_filter;
mod method_routing;
mod not_found;
mod route;
mod strip_prefix;

#[cfg(test)]
mod tests;

pub use self::{into_make_service::IntoMakeService, method_filter::MethodFilter, route::Route};

pub use self::method_routing::{
    any, any_service, delete, delete_service, get, get_service, head, head_service, on, on_service,
    options, options_service, patch, patch_service, post, post_service, put, put_service, trace,
    trace_service, MethodRouter,
};

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct RouteId(u32);

impl RouteId {
    fn next() -> Self {
        use std::sync::atomic::{AtomicU32, Ordering};
        // `AtomicU64` isn't supported on all platforms
        static ID: AtomicU32 = AtomicU32::new(0);
        let id = ID.fetch_add(1, Ordering::Relaxed);
        if id == u32::MAX {
            panic!("Over `u32::MAX` routes created. If you need this, please file an issue.");
        }
        Self(id)
    }
}

/// The router type for composing handlers and services.
pub struct Router<B = Body> {
    routes: HashMap<RouteId, Endpoint<B>>,
    node: Node,
    fallback: Fallback<B>,
    nested_at_root: bool,
    nest_policy: NestPolicy,
    method_policy: MethodPolicy,
    payload_codec: PayloadCodec,
    param_codec: ParamCodec,
    response_policy: ResponsePolicy,
}

#[derive(Clone, Debug)]
struct NestPolicy {
    known_prefixes: Vec<Arc<str>>,
    ensure_leading_slash: bool,
    preserve_query: bool,
}

impl Default for NestPolicy {
    fn default() -> Self {
        Self {
            known_prefixes: Vec::new(),
            ensure_leading_slash: true,
            preserve_query: true,
        }
    }
}

#[derive(Clone, Debug)]
struct MethodPolicy {
    head_fallback: bool,
    strip_head_body: bool,
}

impl Default for MethodPolicy {
    fn default() -> Self {
        Self {
            head_fallback: true,
            strip_head_body: true,
        }
    }
}

#[derive(Clone, Debug)]
struct PayloadCodec {
    json_type: &'static str,
    json_subtype: &'static str,
    allow_json_suffix: bool,
    allow_empty_query: bool,
}

impl Default for PayloadCodec {
    fn default() -> Self {
        Self {
            json_type: "application",
            json_subtype: "json",
            allow_json_suffix: true,
            allow_empty_query: true,
        }
    }
}

#[derive(Clone, Debug)]
struct ParamCodec {
    skip_nest_tail: bool,
    percent_decode: bool,
    merge_existing: bool,
}

impl Default for ParamCodec {
    fn default() -> Self {
        Self {
            skip_nest_tail: true,
            percent_decode: true,
            merge_existing: true,
        }
    }
}

#[derive(Clone, Debug)]
struct ResponsePolicy {
    tsr_code: u16,
    record_original_uri: bool,
    not_found_code: u16,
}

impl Default for ResponsePolicy {
    fn default() -> Self {
        Self {
            tsr_code: 301,
            record_original_uri: true,
            not_found_code: 404,
        }
    }
}

impl<B> Clone for Router<B> {
    fn clone(&self) -> Self {
        Self {
            routes: self.routes.clone(),
            node: self.node.clone(),
            fallback: self.fallback.clone(),
            nested_at_root: self.nested_at_root,
            nest_policy: self.nest_policy.clone(),
            method_policy: self.method_policy.clone(),
            payload_codec: self.payload_codec.clone(),
            param_codec: self.param_codec.clone(),
            response_policy: self.response_policy.clone(),
        }
    }
}

impl<B> fmt::Debug for Router<B> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Router")
            .field("routes", &self.routes)
            .field("node", &self.node)
            .field("fallback", &self.fallback)
            .field("nested_at_root", &self.nested_at_root)
            .finish()
    }
}

impl<B> Default for Router<B>
where
    B: Send + 'static,
{
    fn default() -> Self {
        Self::new()
    }
}

pub(crate) const NEST_TAIL_PARAM: &str = "axum_nest";
const NEST_TAIL_PARAM_CAPTURE: &str = "/*axum_nest";

impl<B> Router<B>
where
    B: Send + 'static,
{
    /// Create a new `Router`.
    ///
    /// Unless you add additional routes this will respond with `404 Not Found` to
    /// all requests.
    pub fn new() -> Self {
        Self {
            routes: Default::default(),
            node: Default::default(),
            fallback: Fallback::Default(Route::new(NotFound)),
            nested_at_root: false,
            nest_policy: NestPolicy::default(),
            method_policy: MethodPolicy::default(),
            payload_codec: PayloadCodec::default(),
            param_codec: ParamCodec::default(),
            response_policy: ResponsePolicy::default(),
        }
    }

    #[doc = include_str!("../docs/routing/route.md")]
    pub fn route<T>(mut self, path: &str, service: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Invalid route: empty path");
        }

        let service = match try_downcast::<Router<B>, _>(service) {
            Ok(_) => {
                panic!("Invalid route: `Router::route` cannot be used with `Router`s. Use `Router::nest` instead")
            }
            Err(svc) => svc,
        };

        let id = RouteId::next();

        let service = match try_downcast::<MethodRouter<B, Infallible>, _>(service) {
            Ok(method_router) => {
                if let Some((route_id, Endpoint::MethodRouter(prev_method_router))) = self
                    .node
                    .path_to_route_id
                    .get(path)
                    .and_then(|route_id| self.routes.get(route_id).map(|svc| (*route_id, svc)))
                {
                    // if we're adding a new `MethodRouter` to a route that already has one just
                    // merge them. This makes `.route("/", get(_)).route("/", post(_))` work
                    let service =
                        Endpoint::MethodRouter(prev_method_router.clone().merge(method_router));
                    self.routes.insert(route_id, service);
                    return self;
                } else {
                    Endpoint::MethodRouter(method_router)
                }
            }
            Err(service) => Endpoint::Route(Route::new(service)),
        };

        if let Err(err) = self.node.insert(path, id) {
            self.panic_on_matchit_error(err);
        }

        self.routes.insert(id, service);

        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    pub fn nest<T>(mut self, path: &str, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        if path.is_empty() {
            panic!("Invalid route: empty path");
        }

        if path.contains('*') {
            panic!("Invalid route: nested routes cannot contain wildcards (*)");
        }

        let prefix = path;

        if path == "/" {
            self.nested_at_root = true;
        }

        self.remember_nested_prefix(path);

        match try_downcast::<Router<B>, _>(svc) {
            // if the user is nesting a `Router` we can implement nesting
            // by simplying copying all the routes and adding the prefix in
            // front
            Ok(router) => {
                let Router {
                    mut routes,
                    node,
                    fallback,
                    // nesting a router that has something nested at root
                    // doesn't mean something is nested at root in _this_ router
                    // thus we don't need to propagate that
                    nested_at_root: _,
                    ..
                } = router;

                if let Fallback::Custom(_) = fallback {
                    panic!("Cannot nest `Router`s that has a fallback");
                }

                for (id, nested_path) in node.route_id_to_path {
                    let route = routes.remove(&id).unwrap();
                    let full_path = if &*nested_path == "/" {
                        path.to_owned()
                    } else {
                        format!("{}{}", path, nested_path)
                    };
                    self = match route {
                        Endpoint::MethodRouter(method_router) => self.route(
                            &full_path,
                            method_router.layer(layer_fn(|s| StripPrefix::new(s, prefix))),
                        ),
                        Endpoint::Route(route) => {
                            self.route(&full_path, StripPrefix::new(route, prefix))
                        }
                    };
                }

                debug_assert!(routes.is_empty());
            }
            // otherwise we add a wildcard route to the service
            Err(svc) => {
                let path = if path == "/" {
                    format!("/*{}", NEST_TAIL_PARAM)
                } else {
                    format!("{}/*{}", path, NEST_TAIL_PARAM)
                };

                self = self.route(&path, strip_prefix::StripPrefix::new(svc, prefix));
            }
        }

        self
    }

    #[doc = include_str!("../docs/routing/merge.md")]
    pub fn merge(mut self, other: Router<B>) -> Self {
        let Router {
            routes,
            node,
            fallback,
            nested_at_root,
            ..
        } = other;

        for (id, route) in routes {
            let path = node
                .route_id_to_path
                .get(&id)
                .expect("no path for route id. This is a bug in axum. Please file an issue");
            self = match route {
                Endpoint::MethodRouter(route) => self.route(path, route),
                Endpoint::Route(route) => self.route(path, route),
            };
        }

        self.fallback = match (self.fallback, fallback) {
            (Fallback::Default(_), pick @ Fallback::Default(_)) => pick,
            (Fallback::Default(_), pick @ Fallback::Custom(_)) => pick,
            (pick @ Fallback::Custom(_), Fallback::Default(_)) => pick,
            (Fallback::Custom(_), Fallback::Custom(_)) => {
                panic!("Cannot merge two `Router`s that both have a fallback")
            }
        };

        self.nested_at_root = self.nested_at_root || nested_at_root;

        self
    }

    #[doc = include_str!("../docs/routing/layer.md")]
    pub fn layer<L, NewReqBody, NewResBody>(self, layer: L) -> Router<NewReqBody>
    where
        L: Layer<Route<B>>,
        L::Service: Service<Request<NewReqBody>, Response = Response<NewResBody>, Error = Infallible>
            + Clone
            + Send
            + 'static,
        <L::Service as Service<Request<NewReqBody>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        let fallback = self.fallback.map(|svc| Route::new(layer.layer(svc)));

        Router {
            routes,
            node: self.node,
            fallback,
            nested_at_root: self.nested_at_root,
            nest_policy: self.nest_policy,
            method_policy: self.method_policy,
            payload_codec: self.payload_codec,
            param_codec: self.param_codec,
            response_policy: self.response_policy,
        }
    }

    #[doc = include_str!("../docs/routing/route_layer.md")]
    pub fn route_layer<L, NewResBody>(self, layer: L) -> Self
    where
        L: Layer<Route<B>>,
        L::Service: Service<Request<B>, Response = Response<NewResBody>, Error = Infallible>
            + Clone
            + Send
            + 'static,
        <L::Service as Service<Request<B>>>::Future: Send + 'static,
        NewResBody: HttpBody<Data = Bytes> + Send + 'static,
        NewResBody::Error: Into<BoxError>,
    {
        let layer = ServiceBuilder::new()
            .layer(MapResponseBodyLayer::new(boxed))
            .layer(layer)
            .into_inner();

        let routes = self
            .routes
            .into_iter()
            .map(|(id, route)| {
                let route = match route {
                    Endpoint::MethodRouter(method_router) => {
                        Endpoint::MethodRouter(method_router.layer(&layer))
                    }
                    Endpoint::Route(route) => Endpoint::Route(Route::new(layer.layer(route))),
                };
                (id, route)
            })
            .collect();

        Router {
            routes,
            node: self.node,
            fallback: self.fallback,
            nested_at_root: self.nested_at_root,
            nest_policy: self.nest_policy,
            method_policy: self.method_policy,
            payload_codec: self.payload_codec,
            param_codec: self.param_codec,
            response_policy: self.response_policy,
        }
    }

    #[doc = include_str!("../docs/routing/fallback.md")]
    pub fn fallback<T>(mut self, svc: T) -> Self
    where
        T: Service<Request<B>, Response = Response, Error = Infallible> + Clone + Send + 'static,
        T::Future: Send + 'static,
    {
        self.fallback = Fallback::Custom(Route::new(svc));
        self
    }

    /// Convert this router into a [`MakeService`], that is a [`Service`] whose
    /// response is another service.
    ///
    /// This is useful when running your application with hyper's
    /// [`Server`](hyper::server::Server):
    ///
    /// ```
    /// use axum::{
    ///     routing::get,
    ///     Router,
    /// };
    ///
    /// let app = Router::new().route("/", get(|| async { "Hi!" }));
    ///
    /// # async {
    /// axum::Server::bind(&"0.0.0.0:3000".parse().unwrap())
    ///     .serve(app.into_make_service())
    ///     .await
    ///     .expect("server failed");
    /// # };
    /// ```
    ///
    /// [`MakeService`]: tower::make::MakeService
    pub fn into_make_service(self) -> IntoMakeService<Self> {
        IntoMakeService::new(self)
    }

    #[doc = include_str!("../docs/routing/into_make_service_with_connect_info.md")]
    pub fn into_make_service_with_connect_info<C, Target>(
        self,
    ) -> IntoMakeServiceWithConnectInfo<Self, C>
    where
        C: Connected<Target>,
    {
        IntoMakeServiceWithConnectInfo::new(self)
    }

    #[inline]
    fn call_route(&self, match_: matchit::Match<&RouteId>, mut req: Request<B>) -> RouterFuture<B> {
        let id = *match_.value;
        self.capture_route_id(&mut req, id);

        if let Some(matched_path) = self.node.route_id_to_path.get(&id).cloned() {
            let combined = self.combine_matched_path(req.extensions().get::<MatchedPath>(), matched_path);
            req.extensions_mut().insert(MatchedPath(combined));
        } else {
            #[cfg(debug_assertions)]
            panic!("should always have a matched path for a route id");
        }

        let params = self.collect_match_params(&match_);

        self.store_url_params(&mut req, params);

        let mut route = self
            .routes
            .get(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
            .clone();

        let future = match &mut route {
            Endpoint::MethodRouter(inner) => inner.call(req),
            Endpoint::Route(inner) => inner.call(req),
        };
        RouterFuture::from_future(future)
    }

    fn panic_on_matchit_error(&self, err: matchit::InsertError) {
        if self.nested_at_root {
            panic!(
                "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                err,
            );
        } else {
            panic!("Invalid route: {}", err);
        }
    }
}

impl<B> Service<Request<B>> for Router<B>
where
    B: Send + 'static,
{
    type Response = Response;
    type Error = Infallible;
    type Future = RouterFuture<B>;

    #[inline]
    fn poll_ready(&mut self, _: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        Poll::Ready(Ok(()))
    }

    #[inline]
    fn call(&mut self, mut req: Request<B>) -> Self::Future {
        self.maybe_store_original_uri(&mut req);

        let path = req.uri().path().to_owned();

        match self.node.at(&path) {
            Ok(match_) => self.call_route(match_, req),
            Err(err) => {
                if err.tsr() {
                    let target = self.trailing_slash_target(&path);
                    let redirect_to = self.rewrite_uri_path(req.uri(), &target);
                    let res = self.moved_permanently_response(redirect_to);
                    RouterFuture::from_response(res)
                } else {
                    match &self.fallback {
                        Fallback::Default(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                        Fallback::Custom(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                    }
                }
            }
        }
    }
}


impl<B> Router<B> {
    fn remember_nested_prefix(&mut self, prefix: &str) {
        if prefix.is_empty() {
            return;
        }
        if self
            .nest_policy
            .known_prefixes
            .iter()
            .any(|known| known.as_ref() == prefix)
        {
            return;
        }
        self.nest_policy.known_prefixes.push(Arc::from(prefix));
    }

    fn resolve_known_prefix<'a>(&'a self, prefix: &'a str) -> &'a str {
        if let Some(known) = self
            .nest_policy
            .known_prefixes
            .iter()
            .find(|known| known.as_ref() == prefix)
        {
            known.as_ref()
        } else {
            prefix
        }
    }

    fn normalize_prefix<'a>(&self, prefix: &'a str) -> Cow<'a, str> {
        if prefix.is_empty() {
            return Cow::Borrowed(prefix);
        }
        if self.nest_policy.ensure_leading_slash && !prefix.starts_with('/') {
            Cow::Owned(format!("/{}", prefix))
        } else {
            Cow::Borrowed(prefix)
        }
    }

    fn ensure_absolute_path<'a>(&self, path: &'a str) -> Cow<'a, str> {
        if path.starts_with('/') {
            Cow::Borrowed(path)
        } else if self.nest_policy.ensure_leading_slash {
            if path.is_empty() {
                Cow::Borrowed("/")
            } else {
                Cow::Owned(format!("/{}", path))
            }
        } else if path.is_empty() {
            Cow::Borrowed("/")
        } else {
            Cow::Borrowed(path)
        }
    }

    fn strip_uri_path(&self, path: &str, prefix: &str) -> String {
        let prefix = self.resolve_known_prefix(prefix);
        let stripped = if let Some(rest) = path.strip_prefix(prefix) {
            rest
        } else if self.nest_policy.ensure_leading_slash {
            path
        } else {
            path
        };
        self.ensure_absolute_path(stripped).into_owned()
    }

    fn split_path_and_query<'a>(&self, uri: &'a Uri) -> Option<(&'a str, Option<&'a str>)> {
        uri.path_and_query().map(|pq| {
            let query = if self.nest_policy.preserve_query {
                pq.query()
            } else {
                None
            };
            (pq.path(), query)
        })
    }

    fn join_path_and_query(&self, path: &str, query: Option<&str>) -> Option<http::uri::PathAndQuery> {
        let path = self.ensure_absolute_path(path);
        if self.nest_policy.preserve_query {
            if let Some(query) = query {
                Some(
                    format!("{}?{}", path, query)
                        .parse::<http::uri::PathAndQuery>()
                        .unwrap(),
                )
            } else {
                Some(path.parse().unwrap())
            }
        } else {
            Some(path.parse().unwrap())
        }
    }

    fn copy_uri_scheme_authority(&self, uri: &Uri) -> http::uri::Parts {
        let mut parts = http::uri::Parts::default();
        parts.scheme = uri.scheme().cloned();
        parts.authority = uri.authority().cloned();
        let _ = self.nest_policy.ensure_leading_slash;
        parts
    }

    pub(crate) fn rebuild_uri(&self, uri: &Uri, new_path: &str) -> Uri {
        let query = if let Some((_, query)) = self.split_path_and_query(uri) {
            query
        } else if self.nest_policy.preserve_query {
            None
        } else {
            None
        };
        let path_and_query = self.join_path_and_query(new_path, query);
        let mut parts = self.copy_uri_scheme_authority(uri);
        parts.path_and_query = path_and_query;
        Uri::from_parts(parts).unwrap()
    }

    pub(crate) fn rewrite_uri_with_prefix(&self, uri: &Uri, prefix: &str) -> Uri {
        let prefix = self.normalize_prefix(prefix);
        if prefix.is_empty() || prefix.as_ref() == "/" {
            return self.rebuild_uri(uri, uri.path());
        }
        if !self.prefix_matches_uri(uri, prefix.as_ref())
            && self.nest_policy.ensure_leading_slash
        {
            return self.rebuild_uri(uri, uri.path());
        }
        let remainder = self.nested_path_remainder(uri.path(), prefix.as_ref());
        let stripped = self.strip_uri_path(uri.path(), prefix.as_ref());
        if remainder.starts_with('/') || stripped.starts_with('/') {
            self.rebuild_uri(uri, stripped.as_str())
        } else {
            self.rebuild_uri(uri, stripped.as_str())
        }
    }

    pub(crate) fn rewrite_uri_path(&self, uri: &Uri, new_path: &str) -> Uri {
        let new_path = if self.nest_policy.ensure_leading_slash {
            new_path
        } else {
            new_path
        };
        self.rebuild_uri(uri, new_path)
    }

    fn prefix_matches_uri(&self, uri: &Uri, prefix: &str) -> bool {
        let prefix = self.resolve_known_prefix(prefix);
        if prefix.is_empty() {
            true
        } else if uri.path() == prefix {
            true
        } else if self.nest_policy.ensure_leading_slash && prefix == "/" {
            true
        } else {
            uri.path().starts_with(prefix)
        }
    }

    fn nested_path_remainder<'a>(&self, path: &'a str, prefix: &str) -> &'a str {
        let prefix = self.resolve_known_prefix(prefix);
        if let Some(rest) = path.strip_prefix(prefix) {
            if rest.is_empty() {
                "/"
            } else if self.nest_policy.ensure_leading_slash && !rest.starts_with('/') {
                rest
            } else {
                rest
            }
        } else {
            path
        }
    }

    fn trailing_slash_target(&self, path: &str) -> String {
        if let Some(without_tsr) = path.strip_suffix('/') {
            if self.nest_policy.ensure_leading_slash && !without_tsr.starts_with('/') {
                format!("/{}", without_tsr)
            } else {
                without_tsr.to_owned()
            }
        } else if path.is_empty() {
            "/".to_owned()
        } else {
            format!("{}/", path)
        }
    }
}

